    if(scheduleAction==='event.create'||scheduleAction==='event.update')options={...options,title,description:content,zone,...(allDay?{allDay:true,startDate:start,endDate:end}:{allDay:false,startLocal:start,endLocal:end,...(fold===''?{}:{fold:Number(fold),endFold:Number(fold)})}),allowConflict,fixed};
    if(scheduleAction==='event.update'||scheduleAction==='event.cancel'){need(event,'اختر حدثًا حاليًا.','Choose a current event.');options={...options,eventId:event.id,expectedVersion:event.version};delete options.calendarId;}
