     if(op!=='conflicts')value.tasks=tasks.map(v=>({id:v.id,title:v.title,minutes:v.minutes===''?null:numeric(v.minutes,0,10080,'minutes'),priority:numeric(v.priority,0,100,'priority'),dependsOn:v.depends.split(',').map(x=>x.trim()).filter(Boolean)}));
     if(op==='shift'){need(day&&start&&end,'حدد تاريخ الوردية ووقتيها.','Specify shift date and times.');value.shifts=[{id:'shift-1',title,startDate:day,startTime:start,endTime:end,endNextDay:overnight,commuteBeforeMinutes:commuteBefore===''?null:numeric(commuteBefore,0,240,'commute before'),commuteAfterMinutes:commuteAfter===''?null:numeric(commuteAfter,0,240,'commute after'),restAfterMinutes:restAfter===''?null:numeric(restAfter,0,2880,'rest after'),...(fold===''?{}:{foldStart:Number(fold),foldEnd:Number(fold)})}];}
     if(op==='replan'){need(scenario.trim(),'حدد سبب إعادة التخطيط والفترة غير المتاحة.','Describe the reason and unavailable interval.');value.scenario={reason:scenario,unavailable:[{id:'unavailable-1',start:local(start),end:local(end)}]};}
