 function taskRows(){return <section><h4>{op==='agenda'?t('بنود الاجتماع','Agenda items'):t('المهام ومددها','Tasks and durations')}</h4>{tasks.map((v,i)=><fieldset key={v.id} className="skills-research"><legend>{t('بند','Item')} {i+1}</legend>{textField(t('العنوان','Title')+' '+(i+1),v.title,x=>setTasks(old=>old.map(r=>r.id===v.id?{...r,title:x}:r)))}{textField(t('الدقائق؛ فارغ إذا لم تُعرف','Minutes; blank if unknown')+' '+(i+1),v.minutes,x=>setTasks(old=>old.map(r=>r.id===v.id?{...r,minutes:x}:r)))}{op!=='agenda'&&textField(t('الأولوية من 0 إلى 100','Priority 0–100')+' '+(i+1),v.priority,x=>setTasks(old=>old.map(r=>r.id===v.id?{...r,priority:x}:r)))}{tasks.length>1&&<fieldset><legend>{t('يعتمد على','Depends on')}</legend>{tasks.filter(other=>other.id!==v.id).map(other=><label className="skills-check" key={other.id}><input type="checkbox" checked={v.depends.split(',').includes(other.id)} onChange={e=>setTasks(old=>old.map(item=>item.id===v.id?{...item,depends:(e.target.checked?[...item.depends.split(',').filter(Boolean),other.id]:item.depends.split(',').filter(x=>x!==other.id)).join(',')}:item))}/>{other.title||t('بند بلا عنوان','Untitled item')}</label>)}</fieldset>}<button type="button" className="text-button" disabled={tasks.length<=1} onClick={()=>setTasks(old=>old.filter(r=>r.id!==v.id).map(r=>({...r,depends:r.depends.split(',').filter(id=>id!==v.id).join(',')})))}><Trash2 size={14}/>{t('إزالة البند','Remove item')}</button></fieldset>)}<button type="button" className="text-button" disabled={tasks.length>=30} onClick={()=>setTasks(old=>[...old,row()])}><Plus size={14}/>{t('إضافة بند','Add item')}</button></section>;}
 function windowsForm(values:TimedRow[],set:(v:TimedRow[])=>void,label:string,buffers=false){return <section><h4>{label}</h4>{values.map((v,i)=><fieldset key={v.id} className="skills-research"><legend>{label} {i+1}</legend>{textField(t('البداية','Start')+' '+label+' '+(i+1),v.start,x=>set(values.map(r=>r.id===v.id?{...r,start:x}:r)),'datetime-local')}{textField(t('النهاية','End')+' '+label+' '+(i+1),v.end,x=>set(values.map(r=>r.id===v.id?{...r,end:x}:r)),'datetime-local')}{buffers&&<>{textField(t('هامش قبل الالتزام بالدقائق','Buffer before commitment in minutes')+' '+(i+1),v.bufferBefore,x=>set(values.map(r=>r.id===v.id?{...r,bufferBefore:x}:r)))}{textField(t('هامش بعد الالتزام بالدقائق','Buffer after commitment in minutes')+' '+(i+1),v.bufferAfter,x=>set(values.map(r=>r.id===v.id?{...r,bufferAfter:x}:r)))}</>}<button type="button" className="text-button" onClick={()=>set(values.filter(r=>r.id!==v.id))}>{t('إزالة الفترة','Remove interval')}</button></fieldset>)}<button type="button" className="text-button" disabled={values.length>=20} onClick={()=>set([...values,row()])}><Plus size={14}/>{t('إضافة فترة','Add interval')}</button></section>;}
